CREATE TABLE IF NOT EXISTS advancement_config_changes(id TEXT PRIMARY KEY,scope TEXT NOT NULL CHECK(json_valid(scope)),scope_key TEXT NOT NULL,base_revision INTEGER NOT NULL,config TEXT NOT NULL CHECK(json_valid(config)),fingerprint TEXT NOT NULL,actor_id TEXT NOT NULL,expires_at INTEGER NOT NULL,applied_revision INTEGER);
CREATE INDEX IF NOT EXISTS advancement_changes_scope ON advancement_config_changes(scope_key,expires_at);
CREATE TABLE IF NOT EXISTS advancement_flags(scope_key TEXT NOT NULL,name TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),revision INTEGER NOT NULL,owner_id TEXT NOT NULL,expires_at INTEGER,reason TEXT NOT NULL,PRIMARY KEY(scope_key,name));
CREATE TABLE IF NOT EXISTS advancement_audit(sequence INTEGER PRIMARY KEY AUTOINCREMENT,organization_id TEXT NOT NULL,actor_id TEXT NOT NULL,operation TEXT NOT NULL,resource_id TEXT NOT NULL,status TEXT NOT NULL,before_revision INTEGER,after_revision INTEGER,previous_hash TEXT NOT NULL,hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS advancement_audit_scope ON advancement_audit(organization_id,sequence DESC);
CREATE TABLE IF NOT EXISTS advancement_adapter_policy(connection_id TEXT PRIMARY KEY,capabilities TEXT NOT NULL CHECK(json_valid(capabilities)),failures INTEGER NOT NULL DEFAULT 0,open_until INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS advancement_adapter_claims(id TEXT PRIMARY KEY,connection_id TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS advancement_adapter_claim_connection ON advancement_adapter_claims(connection_id,expires_at);
CREATE TABLE IF NOT EXISTS advancement_financial_entries(id TEXT PRIMARY KEY,realm TEXT NOT NULL CHECK(realm IN('orders','subscriptions')),project_id TEXT NOT NULL,target_id TEXT NOT NULL,entry_key TEXT NOT NULL,kind TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),currency TEXT NOT NULL,command_id TEXT,event_id TEXT,fingerprint TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(realm,project_id,entry_key));
CREATE INDEX IF NOT EXISTS advancement_financial_target ON advancement_financial_entries(project_id,realm,target_id,created_at);
CREATE TABLE IF NOT EXISTS advancement_reconciliation(id TEXT PRIMARY KEY,scope TEXT NOT NULL CHECK(json_valid(scope)),kind TEXT NOT NULL,target_id TEXT NOT NULL,revision INTEGER NOT NULL,status TEXT NOT NULL,evidence TEXT CHECK(evidence IS NULL OR json_valid(evidence)),resolution TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS advancement_backup_sets(id TEXT PRIMARY KEY,scope TEXT NOT NULL CHECK(json_valid(scope)),manifest TEXT NOT NULL CHECK(json_valid(manifest)),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS advancement_privacy_requests(id TEXT PRIMARY KEY,scope TEXT NOT NULL CHECK(json_valid(scope)),subject_id TEXT NOT NULL,action TEXT NOT NULL,status TEXT NOT NULL,held_reason TEXT,counts TEXT NOT NULL CHECK(json_valid(counts)),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS advancement_privacy_tombstones(project_id TEXT NOT NULL,subject_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(project_id,subject_id));
CREATE TABLE IF NOT EXISTS advancement_lifecycle(organization_id TEXT PRIMARY KEY REFERENCES expansion_organizations(id),revision INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('active','archived','closing')),reason TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS advancement_handoffs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,from_id TEXT NOT NULL,to_id TEXT NOT NULL,expires_at INTEGER NOT NULL,accepted_at TEXT);
CREATE TABLE IF NOT EXISTS advancement_catalog(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,package_id TEXT NOT NULL,version TEXT NOT NULL,integrity TEXT NOT NULL,manifest TEXT NOT NULL CHECK(json_valid(manifest)),status TEXT NOT NULL CHECK(status IN('pending','approved','revoked')),publisher_id TEXT NOT NULL,reviewer_id TEXT,license TEXT NOT NULL,support_contact TEXT NOT NULL,evidence TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(package_id,version));
CREATE TABLE IF NOT EXISTS advancement_usage_observations(operation_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,project_id TEXT NOT NULL,metric TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),fingerprint TEXT NOT NULL,created_at TEXT NOT NULL);
